import {learningBlocks,contents,patchLearningDOM,jumpToConcept,activateVideo} from './learning.js';
import {createStore} from './store.js';
import {grade,recordResponse,mastery,expired,decodeBackup,localDay,diagnosticQuestions} from './core.js';
import {LABS,labState,renderLab,resetLab} from './labs.js';
import {EXERCISES,pythonView,runPython,stopPython} from './python.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let curriculum,exams,expandedContent,videoCatalog,store;
try{[curriculum,exams,expandedContent,videoCatalog]=await Promise.all(['curriculum','exams','lesson-content','videos'].map(x=>fetch(new URL(`../data/${x}.json`,import.meta.url)).then(r=>{if(!r.ok)throw Error();return r.json();})));}catch{document.querySelector('#app').innerHTML='<main><h1>CAICP Academy</h1><p>Could not load learning content. Serve the folder over HTTP and reload. / 无法加载课程。请通过HTTP提供网站后重试。</p></main>';throw Error('Curriculum unavailable');}
const expandedSections=new Map(expandedContent.sections.map(x=>[x.id,x]));
const concepts=new Map(expandedContent.sections.flatMap(x=>x.blocks.map(b=>[b.id,b])));
const lessons=new Map(curriculum.lessons.map(l=>[l.id,l]));const questions=new Map([...curriculum.questions,...exams.questions].map(q=>[q.id,q]));
const ids={lessons:new Set(lessons.keys()),questions};
try{store=createStore(ids);}catch{store=createStore(ids,{getItem(){throw Error();},setItem(){throw Error();}});}
const s=()=>store.state;const b=(en,zh)=>s().settings.lang==='zh'?zh:en;const loc=v=>v?.[s().settings.lang]??'';
let renderedLesson=null;
let offlineReady=false,registration=null,search='',levelFilter='all',glossarySearch='',pendingImport=null;
const root=document.querySelector('#app');const button=(action,en,zh,cl='',extra='')=>`<button class="${cl}" data-action="${action}" ${extra}>${b(en,zh)}</button>`;
const link=(url,en,zh,cl='')=>`<a class="button ${cl}" href="#${url}">${b(en,zh)}</a>`;
const title=(eyebrow,en,zh,descEn='',descZh='')=>`<div class="welcome"><div class="eyebrow">${b(eyebrow[0],eyebrow[1])}</div><h1>${b(en,zh)}</h1>${descEn?`<p class="muted">${b(descEn,descZh)}</p>`:''}</div>`;
const routeName=r=>`${r[0]} · ${b('Round','第')}${b(' ','')}${r[1]}${b('','轮')}`;
const now=()=>Date.now();
const art=`<svg viewBox="0 0 200 220" aria-hidden="true"><circle cx="100" cy="105" r="84" fill="var(--lime)" opacity=".8"/><path d="M35 70L100 50l65 20v90l-65 20-65-20z" fill="var(--paper)"/><path d="M100 50v130M35 70l65 20 65-20" stroke="var(--teal)" stroke-width="2" fill="none"/><path d="M50 98l35 11m-35 8l35 11m-35 8l22 7" stroke="var(--teal)" stroke-width="3"/><circle cx="135" cy="120" r="16" stroke="var(--indigo)" fill="none" stroke-width="2"/><path d="M122 108l26 24m-13-28v32" stroke="var(--indigo)"/><circle cx="39" cy="47" r="5" fill="var(--teal)"/><path d="M167 43v16m-8-8h16M30 183v12m-6-6h12" stroke="var(--teal)" stroke-width="2"/></svg>`;
function save(){store.save();const main=document.querySelector('#main');if(store.error&&main&&!document.querySelector('#storage-warning')){const warning=document.createElement('div');warning.id='storage-warning';warning.className='notice warning';warning.setAttribute('role','alert');warning.textContent=b('Storage is unavailable. Export your progress before closing this page.','存储不可用，关闭前请导出进度。');main.prepend(warning);}}
function notify(en,zh){const t=document.querySelector('#toast');t.textContent=b(en,zh);t.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.style.display='none',4000);}
function route(){return (location.hash.slice(1)||'home').split('/');}
function stats(){const responses=s().responses,day=localDay(now()),today=responses.filter(r=>localDay(r.at)===day).length;return {today,correct:responses.filter(r=>r.correct).length,total:responses.length,due:Object.keys(s().reviews).filter(id=>s().reviews[id].due<=now()),mistakes:[...new Set(responses.filter(r=>!r.correct).map(r=>r.questionId))]};}
function lessonRow(l){const m=mastery(s(),l.id,questions);return `<div class="lesson-row"><span class="lesson-number">${s().completed.includes(l.id)?'✓':l.id}</span><div class="grow"><h3><a href="#lesson/${l.id}">${esc(loc(l.title))}</a></h3><div class="small muted">${l.level} · ${b('Book p.','教材第')}${l.page}${b('','页')} ${m.total?`· ${b('Practice','练习')} ${m.correct}/${m.total}`:''}</div></div><a class="button" href="#lesson/${l.id}">${b('Open','学习')} →</a></div>`;}
function dashboard(){const st=stats(),path=curriculum.routes[s().settings.route],done=path.filter(id=>s().completed.includes(id)).length,next=path.find(id=>!s().completed.includes(id))||path[0],last=lessons.get(s().lastLesson),weak=path.map(id=>({l:lessons.get(id),m:mastery(s(),id,questions)})).filter(x=>x.m.total&&x.m.percent<80).sort((a,c)=>a.m.percent-c.m.percent);return `${title(['YOUR LEARNING SPACE','你的学习空间'],'A little progress, every day.','每天前进一点点。','Choose one idea. Explore it. Make it yours.','选择一个概念，探索它，真正掌握它。')}<div class="grid two"><section class="card continue-card"><div class="continue-copy"><div class="eyebrow">${b('Continue your journey','继续你的旅程')} · ${routeName(s().settings.route)}</div><h2>${esc(loc(last.title))}</h2><p class="muted">${b('Return to your last lesson, or follow the next step in your selected study route.','返回上次课程，或按所选路线学习下一节。')}</p><div class="flex wrap">${link('lesson/'+last.id,'Continue learning →','继续学习 →','primary')}${link('lesson/'+next,'Next in route','路线下一节')}</div></div><div class="continue-art">${art}</div></section><section class="card review-card"><div><div class="flex between"><h3>${b('Ready for recall?','准备回忆了吗？')}</h3><span class="tag">${b('SPACED REVIEW','间隔复习')}</span></div><div class="review-count">${st.due.length}</div><p class="muted small">${b('questions due for review. Revisit ideas just before they fade.','道题待复习。在遗忘前重温知识。')}</p></div>${button('due-review',st.due.length?'Start review →':'Build your review queue',st.due.length?'开始复习 →':'建立复习队列','secondary')}</section></div><div class="grid four section"><div class="card stat"><span class="label">${b('Lessons completed','已完成课程')}</span><div class="number">${s().completed.length}<span class="small muted"> / 38</span></div></div><div class="card stat"><span class="label">${b('Practice accuracy','练习正确率')}</span><div class="number">${st.total?Math.round(st.correct/st.total*100)+'%':'—'}</div></div><div class="card stat"><span class="label">${b('Today’s answers','今日答题')}</span><div class="number">${st.today}<span class="small muted">${s().settings.dailyGoal?' / '+s().settings.dailyGoal:''}</span></div></div><div class="card stat"><span class="label">${b('Selected route','所选路线')}</span><div class="number">${s().settings.route}<span class="small muted"> · ${done}/${path.length}</span></div></div></div><div class="grid two section"><section class="card"><div class="flex between section-title"><h2>${b('Your next steps','接下来的学习')}</h2>${link('learn','All lessons ↗','全部课程 ↗')}</div>${(weak.length?weak.slice(0,3).map(x=>x.l):path.filter(id=>!s().completed.includes(id)).slice(0,3).map(id=>lessons.get(id))).map(lessonRow).join('')||`<p>${b('Route completed. Explore a new route or revisit your mistakes.','路线已完成，可探索新路线或复习错题。')}</p>`}<div class="progress"><span style="width:${done/path.length*100}%"></span></div><p class="small muted" style="margin:10px 0 0">${b('Completion and understanding are separate: practice measures your current recall.','完成课程与理解程度分别记录，练习反映当前掌握情况。')}</p></section><div class="grid"><section class="card focus-card"><div class="flex between"><h3>${b('Make room for focus','留一点专注时间')}</h3><span>◷</span></div><p class="small muted">${b('A quiet 25-minute session, one idea at a time.','安静学习25分钟，一次专注一个概念。')}</p><div class="flex between"><span id="focus-clock" class="clock" style="color:inherit">${s().focusEndsAt?formatTime(s().focusEndsAt-now()):'25:00'}</span>${button(s().focusEndsAt?'focus-stop':'focus-start',s().focusEndsAt?'Stop':'Start session',s().focusEndsAt?'停止':'开始专注')}</div></section><section class="card"><h3>${b('Small wins count','每个小进步都值得记录')}</h3><div class="flex wrap">${[[s().completed.length>=1,'First step','第一步'],[st.total>=10,'Ten thoughtful answers','认真答十题'],[s().completed.length>=8,'Growing knowledge','知识在生长']].map(([ok,en,zh])=>`<span class="badge ${ok?'':'locked'}">${ok?'✦':'◇'} ${b(en,zh)}</span>`).join('')}</div></section></div></div><div class="section"><div class="flex between section-title"><h2>${b('Learn by trying','在尝试中学习')}</h2>${link('labs','Explore all labs ↗','探索全部实验 ↗')}</div><div class="grid three">${LABS.filter(x=>['binary','knn','gradient'].includes(x[0])).map((x,i)=>`<a class="card topic-card" href="#lab/${x[0]}"><div class="topic-icon">${['⌕','⠿','∿'][i]}</div><h3>${b(x[1],x[2])}</h3><p class="small muted">${b('Change an input and watch the reasoning unfold.','改变输入，观察推理过程。')}</p><span class="small">${b('Try the lab','试一试')} →</span></a>`).join('')}</div></div>`;}
function studyGuidance(){return `<details class="card study-guide"><summary>${b('How to study: understand, calculate, transfer','怎样学习：理解、计算、迁移')}</summary><ol>${expandedContent.studyGuide.map(g=>`<li>${esc(loc(g))}</li>`).join('')}</ol><p class="source">${b('Book v0.9 · Appendix C · printed pp.247–249','教材v0.9 · 附录C · 印刷页247–249')}</p></details>`;}
function learn(){const filtered=curriculum.lessons.filter(l=>(levelFilter==='all'||curriculum.routes[s().settings.route].includes(l.id))&&(!search||JSON.stringify([l.title,l.body,l.id,expandedSections.get(l.id)]).toLowerCase().includes(search.toLowerCase())));return `${title(['38 LESSONS • 8 CHAPTERS','38节课程 · 8章内容'],'Follow your curiosity.','循着好奇心学习。','A guided route helps you choose; every lesson is always available.','路线帮助你选择，所有课程始终开放。')}<div class="filters"><input id="lesson-search" placeholder="${b('Search topics, terms, or section number…','搜索主题、术语或节号…')}" aria-label="${b('Search lessons','搜索课程')}" value="${esc(search)}"><select id="route-select" aria-label="${b('Study route','学习路线')}">${Object.keys(curriculum.routes).map(r=>`<option value="${r}" ${r===s().settings.route?'selected':''}>${routeName(r)}</option>`).join('')}</select><select id="level-filter" aria-label="${b('Show lessons','显示课程')}"><option value="all">${b('All lessons','所有课程')}</option><option value="route" ${levelFilter==='route'?'selected':''}>${b('Selected route','所选路线')}</option></select></div><div class="notice">${b('Routes follow book v0.9 appendix A/C. A section may contain material beyond your current level; focus on the route’s intended skill. This is a versioned study guide, not a live official syllabus.','路线依据教材v0.9附录A/C。某节可能包含超出当前级别的内容，应按路线目标能力学习。这里是版本化学习指南，不是实时官方大纲。')}</div>${studyGuidance()}${curriculum.chapters.map((c,i)=>{const group=filtered.filter(l=>l.chapter===i+1);return group.length?`<section class="card section"><div class="eyebrow">${b('CHAPTER','第')}${i+1}${b('','章')}</div><h2>${esc(loc(c))}</h2>${group.map(lessonRow).join('')}</section>`:'';}).join('')||empty()}`;}
function lesson(id){const l=lessons.get(id);if(!l)return empty();s().lastLesson=id;save();const index=curriculum.lessons.indexOf(l),next=curriculum.lessons[index+1];return `<div class="welcome"><div class="eyebrow">${b('CHAPTER','第')}${l.chapter}${b('','章')} · ${l.id} · ${b('BOOK PAGE','教材页码')} ${l.page}</div><h1>${esc(loc(l.title))}</h1><div class="tags"><span class="tag">${l.level} · ${b('First focus: round','首次重点：第')}${l.round}${b('','轮')}</span><span class="tag">${esc(loc(l.skill))}</span><span class="tag">${b('CORE + EXPANDABLE DETAIL','核心讲解＋展开细节')}</span></div></div><div class="reading-layout"><article class="reading"><details class="mobile-contents card"><summary>${b('In this lesson','本节目录')}</summary>${contents(expandedSections.get(id),s().settings.lang)}</details>${learningBlocks(expandedSections.get(id),videoCatalog,s().settings.lang)}<section class="card example"><div class="eyebrow">${b('WORKED EXAMPLE','例题解析')}</div><p>${esc(loc(l.example))}</p></section><section class="card mistake"><h2>${b('Watch for this','留意这个误区')}</h2><p>${esc(loc(l.mistake))}</p></section><section class="card"><h2>${b('Make it stick','让知识留下来')}</h2><p>${b('Try a small experiment, then answer three checks without looking back. Explain why each statement is true or false.','先做小实验，再不看讲解答三道检查题，说明每个陈述为什么对或错。')}</p><div class="flex wrap">${link('lab/'+l.lab,'Try a visual lab ↗','体验可视化实验 ↗')}${button('lesson-quiz','Check understanding →','检查理解 →','primary',`data-id="${id}"`)}</div></section><div class="flex between wrap">${button('complete',s().completed.includes(id)?'Mark as unfinished':'Mark lesson complete',s().completed.includes(id)?'标为未完成':'标为已完成','secondary',`data-id="${id}"`)}${next?link('lesson/'+next.id,'Next lesson →','下一节 →'):link('learn','Back to curriculum','返回课程')}</div><p class="source">${b('Adapted from','改编自')} 陈峥 · 从零开始学人工智能：中学生CAICP学习指南 · v0.9 · §${id}, p.${l.page} · CC BY-NC-SA 4.0</p></article><aside class="reading-aside"><section class="card">${contents(expandedSections.get(id),s().settings.lang)}</section><section class="card"><h3>${b('Learning objectives','学习目标')}</h3><ul>${l.objectives.map(o=>`<li>${esc(loc(o))}</li>`).join('')}</ul><h3>${b('Before you begin','开始前')}</h3>${l.prerequisites.length?l.prerequisites.map(p=>`<p><a href="#lesson/${p}">${p} ${esc(loc(lessons.get(p).title))}</a></p>`).join(''):`<p>${b('No prior section required.','无需前置课程。')}</p>`}</section><section class="card">${button('bookmark',s().bookmarks.includes(id)?'★ Bookmarked':'☆ Bookmark',s().bookmarks.includes(id)?'★ 已收藏':'☆ 收藏','',`data-id="${id}"`)}<label for="lesson-notes"><h3 style="margin-top:20px">${b('Your notes','你的笔记')}</h3></label><textarea id="lesson-notes" data-lesson="${id}" rows="7" maxlength="20000" placeholder="${b('Explain it in your own words…','用自己的话解释…')}">${esc(s().notes[id]||'')}</textarea><p class="small muted">${b('Saved as you type, only in this browser.','输入时自动保存，仅在本浏览器中。')}</p></section></aside></div>`;}
function practice(){return `${title(['RECALL • REASON • REFINE','回忆 · 推理 · 改进'],'Practice with purpose.','有目标地练习。','Find gaps, revisit mistakes, and build confidence with evidence.','发现薄弱点，复习错题，用实际练习建立信心。')}<div class="grid three"><section class="card"><div class="topic-icon">⌕</div><h3>${b('Quick diagnostic','快速诊断')}</h3><p class="muted small">${b('12 questions across your selected route. Discover useful next steps.','从所选路线抽取12题，找到下一步学习重点。')}</p>${button('diagnostic','Start diagnostic →','开始诊断 →','primary')}</section><section class="card"><div class="topic-icon">↻</div><h3>${b('Mistake notebook','错题本')}</h3><p class="muted small">${b('Revisit errors and follow explanations back to the relevant concept.','重做错题，并通过解析返回相关概念。')}</p>${link('review','Open notebook →','打开错题本 →')}</section><section class="card"><div class="topic-icon">✦</div><h3>${b('Topic practice','主题练习')}</h3><p class="muted small">${b('Three original checks for every section, with immediate explanations.','每节三道原创检查题，即时查看解析。')}</p>${link('learn','Choose a topic →','选择主题 →')}</section></div><section class="section"><h2>${b('Book practice papers','教材模拟卷')}</h2><p class="muted small">${b('26 questions • 100 points • 90 minutes. Multiple-select questions require the complete correct set. These are the book’s original mock papers, not official exam papers.','26题 · 100分 · 90分钟。多选题须全部选对。这些是教材原创模拟卷，不是官方试卷。')}</p><div class="grid three">${exams.papers.map(p=>`<section class="card"><span class="tag">${p.id} · ${b('ROUND 1','第一轮')}</span><h3 style="margin-top:18px">${esc(loc(p.title))}</h3><p class="small muted">${b('Practice with feedback or simulate a timed paper. Timed answers are revealed only after submission.','可即时反馈练习，或模拟限时考试。限时模式仅交卷后显示答案。')}</p><div class="flex wrap">${button('paper-practice','Practice','练习','',`data-id="${p.id}"`)}${button('paper-exam','Timed paper','限时模拟','primary',`data-id="${p.id}"`)}</div></section>`).join('')}</div></section><section class="card section"><h2>${b('Recent attempts','最近练习')}</h2>${s().attempts.slice(-8).reverse().map(a=>{const result=grade(a,questions);return `<div class="lesson-row"><div class="grow"><h3>${esc(loc(a.title))}</h3><span class="small muted">${new Date(a.submittedAt).toLocaleDateString(s().settings.lang==='en'?'en-US':'zh-CN')} · ${result.earned}/${result.total}</span></div>${button('attempt-open','Review','回顾','',`data-id="${esc(a.id)}"`)}</div>`;}).join('')||`<p class="muted">${b('Your completed attempts will appear here.','完成的练习会显示在这里。')}</p>`}</section>`;}
function empty(en='Nothing here yet.',zh='这里暂时没有内容。'){return `<div class="empty"><p>${b(en,zh)}</p>${link('learn','Explore lessons','浏览课程')}</div>`;}
function bookDiagram(q){if(!q.diagram)return '';if(q.diagram.kind==='bits')return `<div class="book-diagram" aria-hidden="true"><div class="bits">${q.diagram.rows.flat().map(v=>`<span class="${v?'black':''}"></span>`).join('')}</div></div>`;if(q.diagram.kind==='network')return `<div class="book-diagram"><div class="small">x₁,x₂ → [ z₁ → ReLU, z₂ → ReLU ] → y</div></div>`;if(q.diagram.kind==='graph')return `<div class="book-diagram small">A → B → C → E → F<br>A → D → E &nbsp; · &nbsp; C → A &nbsp; · &nbsp; F → B</div>`;return `<div class="book-diagram small">y=4: ○ — ○ — ○ — ○ — ○<br>y=3: ○ — ○ — × — ○ — T<br>y=2: ○ — ○ — × — ○ — ○<br>y=1: ○ — ○ — × — ○ — ○<br>y=0: S — ○ — × — ○ — ○<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; x=0 &nbsp; 1 &nbsp; 2 &nbsp; 3 &nbsp; 4</div>`;}
function quiz(){const a=s().active;if(!a)return empty('Choose a practice activity first.','请先选择练习。');if(expired(a)){submit(false);return quiz();}const q=questions.get(a.questionIds[a.index]),selected=a.answers[q.id]||[],reveal=!!a.submittedAt||!!a.graded[q.id],correct=selected.length&&q.answer.length===selected.length&&q.answer.every(x=>selected.includes(x)),result=grade(a,questions);return `${title(['CHECK YOUR UNDERSTANDING','检查理解'],esc(a.title.en),esc(a.title.zh))}${a.submittedAt?`<section class="card section"><div class="flex between wrap"><div><div class="results-score">${result.earned}<span style="font-size:24px"> / ${result.total}</span></div><p class="muted">${b('A study result, not a certification pass prediction. Review each explanation below.','这是学习结果，不是认证通过预测。请回顾下方逐题解析。')}</p></div>${button('retry','Try again','再试一次','secondary')}</div></section>`:''}<div class="quiz-layout section"><section class="card"><div class="flex between quiz-top"><span class="tag">${b('QUESTION','题目')} ${a.index+1}/${a.questionIds.length} · ${q.points} ${b('POINTS','分')} · ${b({single:'SINGLE CHOICE',multiple:'SELECT ALL',boolean:'TRUE / FALSE'}[q.type],{single:'单选',multiple:'多选',boolean:'判断'}[q.type])}</span>${button('flag',a.flags[q.id]?'⚑ Flagged':'⚐ Flag',a.flags[q.id]?'⚑ 已标记':'⚐ 标记')}</div>${q.shared?`<div class="shared">${esc(loc(q.shared))}</div>`:''}<div class="question-prompt">${esc(loc(q.prompt))}</div>${bookDiagram(q)}<fieldset style="border:0;padding:0;margin:20px 0"><legend class="sr-only">${b('Choose your answer','选择答案')}</legend>${q.options.map((v,i)=>`<label class="option ${selected.includes(i)?'selected':''} ${reveal?(q.answer.includes(i)?'correct':selected.includes(i)?'incorrect':''):''}"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="answer" value="${i}" ${selected.includes(i)?'checked':''} ${reveal?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(loc(v))}</span></label>`).join('')}</fieldset>${reveal?`<section class="feedback ${correct?'':'wrong'}"><h3>${correct?b('✓ Correct','✓ 正确'):b('Let’s revisit the reasoning','再看一下推理')}</h3><p><strong>${b('Correct answer','正确答案')}: ${q.answer.map(x=>String.fromCharCode(65+x)).join(', ')}</strong></p><div class="question-prompt small">${esc(loc(q.explanation))}</div>${q.optionExplanations?`<details><summary>${b('Why each choice?','每个选项的原因')}</summary>${q.optionExplanations.map((v,i)=>`<p class="small">${String.fromCharCode(65+i)}. ${esc(loc(v))}</p>`).join('')}</details>`:''}<div class="flex wrap section">${q.lessonIds.map(id=>link('lesson/'+id,`Review §${id}`,`复习§${id}`)).join('')}</div></section>`:''}<div class="flex between wrap section"><div class="flex">${button('quiz-prev','← Previous','← 上一题','',a.index===0?'disabled':'')}${a.kind!=='exam'&&!reveal?button('check','Check answer','检查答案','primary',!selected.length?'disabled':''):''}</div>${a.index<a.questionIds.length-1?button('quiz-next','Next →','下一题 →','secondary'):!a.submittedAt?button('submit','Finish attempt','完成练习','primary'):link('practice','More practice →','更多练习 →')}</div><p class="source">${q.source.kind==='adapted'?b('Adapted from book v0.9','改编自教材v0.9'):b('Original Academy check','Academy原创检查题')} · ${b('Printed p.','印刷页码')} ${q.source.page} · CC BY-NC-SA 4.0</p></section><aside class="quiz-aside"><section class="card">${a.deadline&&!a.submittedAt?`<p class="small muted">${b('Time remaining','剩余时间')}</p><div id="exam-clock" class="clock">${formatTime(a.deadline-now())}</div><p class="small muted">${b('Deadline stays fixed through refreshes.','刷新后截止时间保持不变。')}</p>`:''}<div class="navigator">${a.questionIds.map((id,i)=>`<button aria-label="${b('Question','题目')} ${i+1}" data-action="quiz-jump" data-index="${i}" class="${i===a.index?'current':''} ${a.answers[id]?.length?'answered':''} ${a.flags[id]?'flagged':''}">${i+1}</button>`).join('')}</div>${!a.submittedAt?`<div class="section">${button('submit','Submit attempt','提交练习','primary')}</div>`:''}<p class="small muted section">${b('Filled: answered. Underlined: flagged. Practice explanations appear after checking; timed papers reveal after submission.','填色：已答。底线：已标记。普通练习检查后显示解析；限时模拟交卷后显示。')}</p></section></aside></div>`;}
function reviews(){const st=stats();return `${title(['REVISIT • RECALL • RETAIN','重温 · 回忆 · 保持'],'Your review notebook.','你的复习笔记本。','Every mistake is a useful pointer to the next idea worth revisiting.','每个错误都指向一个值得重温的概念。')}<div class="flex wrap"><span class="pill">${st.due.length} ${b('due','待复习')}</span>${button('due-review','Review due cards','复习到期卡片','primary')}${button('mistake-review','Practice mistakes','练习错题','secondary')}</div><div class="section"><h2>${b('Mistakes to learn from','值得学习的错题')}</h2>${st.mistakes.length?st.mistakes.map(id=>{const q=questions.get(id),last=s().responses.filter(r=>r.questionId===id).at(-1);return `<section class="card section"><div class="flex between"><span class="tag">${last.correct?b('RECOVERED','已纠正'):b('REVISIT','待巩固')} · ${q.level}</span>${button('question-practice','Try again','再练一次','',`data-id="${id}"`)}</div><p class="question-prompt small section">${esc(loc(q.prompt))}</p><details><summary>${b('Show explanation','显示解析')}</summary><p class="question-prompt small">${esc(loc(q.explanation))}</p></details><div class="flex wrap section">${q.lessonIds.map(x=>link('lesson/'+x,'Review §'+x,'复习§'+x)).join('')}</div></section>`;}).join(''):empty('No mistakes recorded yet. Begin with a topic check or diagnostic.','尚无错题，可先做主题检查或诊断。')}</div><section class="card section"><h2>${b('Bookmarks & personal notes','收藏与个人笔记')}</h2>${[...new Set([...s().bookmarks,...Object.keys(s().notes).filter(id=>s().notes[id])])].map(id=>`${lessonRow(lessons.get(id))}${s().notes[id]?`<p class="question-prompt small">${esc(s().notes[id])}</p>`:''}`).join('')||`<p class="muted">${b('Save a bookmark or note inside any lesson.','可在任何课程中收藏或写笔记。')}</p>`}</section>`;}
function labs(){return `${title(['LEARNING, MADE VISIBLE','看得见的学习'],'Change something. Notice what follows.','改变一点，观察结果。','Small experiments reveal the steps behind algorithms and models.','小实验揭示算法与模型背后的步骤。')}<div class="grid three">${LABS.map((l,i)=>`<a class="card topic-card" href="#lab/${l[0]}"><div class="topic-icon">${['⌘','↕','⌕','⠿','⊞','%','∿','↘','⠿','◉','⋈','⊞','%'][i]}</div><h3>${b(l[1],l[2])}</h3><p class="small muted">${b('Adjust inputs, inspect the result, and explain the change.','调整输入，检查结果，并解释变化。')}</p><span class="tag">§${l[3]}</span></a>`).join('')}</div>`;}
function python(){const ex=EXERCISES.find(e=>e.id===s().python.exercise)||EXERCISES[0];return `${title(['PYTHON • IN YOUR BROWSER','Python · 浏览器内运行'],'Think it through. Then run it.','先思考，再运行。','Your code runs locally. Python and optional packages download when you choose Run.','代码在本地运行，点击运行时下载Python与可选库。')}<div class="notice">${b('First runs may need a large download and a working connection to jsDelivr. Stop terminates the worker, including infinite loops; the next run reloads Python. Lessons and visual labs work independently.','首次运行可能下载较大文件，需要能连接jsDelivr。停止会结束工作线程，包括无限循环，下次运行重新加载Python。课程与可视化实验独立运行。')}</div><div class="grid two"><section class="card"><label for="exercise-select">${b('Choose an exercise','选择练习')}</label><select id="exercise-select" style="width:100%;margin:8px 0 18px">${EXERCISES.map(e=>`<option value="${e.id}" ${e.id===ex.id?'selected':''}>${esc(loc(e.title))}</option>`).join('')}</select><p>${esc(loc(ex.instructions))}</p><label class="sr-only" for="python-code">${b('Python code','Python代码')}</label><textarea id="python-code" class="code-editor" maxlength="100000" spellcheck="false">${esc(s().python.drafts[ex.id]??ex.code)}</textarea><label for="python-input" class="small">${b('Program input (one value per line)','程序输入（每行一个值）')}</label><textarea id="python-input" rows="3" maxlength="100000">${esc(s().python.inputs[ex.id]??ex.input)}</textarea><div class="flex wrap section">${button('python-run','▶ Run','▶ 运行','primary',['running','loading'].includes(pythonView.status)?'disabled':'')}${button('python-stop','■ Stop','■ 停止','',!['running','loading'].includes(pythonView.status)?'disabled':'')}${button('python-reset','Reset code','重置代码')}${button('python-hint','Hint','提示')}</div>${pythonView.hint?`<p class="notice section">${esc(loc(ex.hint))}</p>`:''}</section><section class="card"><div class="flex between"><h3>${b('Output & observations','输出与观察')}</h3><span id="python-status" class="tag">${pythonStatus()}</span></div><pre id="python-output" class="output" aria-live="polite">${esc(pythonView.output||b('Your output will appear here.','输出会显示在这里。'))}</pre><div id="python-plots" class="plots">${pythonView.plots.map(x=>`<img src="data:image/png;base64,${x}" alt="${b('Plot generated by your Python code','Python代码生成的图表')}">`).join('')}</div><p class="small muted section">${b('Predict before running. If the output surprises you, trace the variables and check the input types.','运行前先预测。如果输出意外，请追踪变量并检查输入类型。')}</p></section></div>`;}
function pythonStatus(){return b({idle:'Ready',loading:'Downloading / loading…',running:'Running…',done:'Complete',stopped:'Stopped · runtime reset',error:'Could not complete'}[pythonView.status],{idle:'就绪',loading:'下载 / 加载中…',running:'运行中…',done:'完成',stopped:'已停止 · 运行环境已重置',error:'未能完成'}[pythonView.status]);}
function updatePython(){if(route()[0]!=='python')return;const output=document.querySelector('#python-output');if(output)output.textContent=pythonView.output||(pythonView.status==='stopped'?b('Execution stopped. You can run again.','执行已停止，可以重新运行。'):pythonView.status==='done'?b('Program finished without text output.','程序已完成，无文本输出。'):b('Loading Python; first use may take a few minutes.','正在加载Python，首次使用可能需要几分钟。'));const status=document.querySelector('#python-status');if(status)status.textContent=pythonStatus();const plot=document.querySelector('#python-plots');if(plot)plot.innerHTML=pythonView.plots.map(x=>`<img src="data:image/png;base64,${x}" alt="${b('Plot generated by your Python code','Python代码生成的图表')}">`).join('');document.querySelector('[data-action="python-run"]').disabled=['running','loading'].includes(pythonView.status);document.querySelector('[data-action="python-stop"]').disabled=!['running','loading'].includes(pythonView.status);}
function glossary(){return `${title(['WORDS BECOME TOOLS','让术语成为工具'],'A shared vocabulary.','共同的知识语言。','Search in either language. Follow a term back to its lesson.','两种语言都可搜索，点击术语返回相关课程。')}<div class="filters"><input id="glossary-search" value="${esc(glossarySearch)}" placeholder="${b('Search English or Chinese terms…','搜索英文或中文术语…')}" aria-label="${b('Search glossary','搜索术语表')}"></div><div class="glossary-grid">${curriculum.glossary.filter(g=>JSON.stringify(g).toLowerCase().includes(glossarySearch.toLowerCase())).map(g=>`<section class="card"><h3>${esc(loc(g.term))}</h3><p class="small muted">${esc(g.term[s().settings.lang==='en'?'zh':'en'])}</p><p>${esc(loc(g.definition))}</p><a href="#lesson/${g.lessonId}">§${g.lessonId} →</a>${g.source?.pages?`<p class="source">${b('Book v0.9 · printed p.','教材v0.9 · 印刷页')} ${g.source.pages.join(', ')}</p>`:''}</section>`).join('')||empty()}</div>`;}
function settings(){return `${title(['MAKE THIS SPACE YOURS','让空间适合你'],'Settings & your progress.','设置与你的进度。','Your learning record lives in this browser. Export a backup before changing devices or clearing browser data.','学习记录保存在此浏览器中，更换设备或清除浏览器数据前请导出备份。')}<div class="grid two settings-grid"><section class="card"><h2>${b('Study preferences','学习偏好')}</h2><label>${b('Study route','学习路线')}<select id="route-select">${Object.keys(curriculum.routes).map(r=>`<option value="${r}" ${r===s().settings.route?'selected':''}>${routeName(r)}</option>`).join('')}</select></label><label>${b('Daily answer goal (0 to disable)','每日答题目标（0关闭）')}<input id="goal-input" type="number" min="0" max="100" value="${s().settings.dailyGoal}"></label><label>${b('Appearance','外观')}<select id="theme-select"><option value="light">${b('Light','浅色')}</option><option value="dark" ${s().settings.theme==='dark'?'selected':''}>${b('Dark','深色')}</option></select></label><div class="notice small">${b('No accounts, tracking, or server-held progress. Browser storage is specific to the website address and browser profile. JSON exports include your notes, answers and code drafts.','无账号、追踪或服务器保存进度。浏览器存储与网站地址和浏览器配置相关。JSON导出包含笔记、答案和代码草稿。')}</div></section><div class="grid"><section class="card"><h2>${b('A backup you can take with you','随身带走的备份')}</h2><p class="muted small">${b('Export everything. Import validates the file and previews its contents before replacing your current record. A current-state backup downloads before replacement.','导出所有记录。导入会校验文件并预览，确认后才替换当前记录。替换前下载当前记录的备份。')}</p><div class="flex wrap">${button('export','↓ Export progress','↓ 导出进度','primary')}${button('import','↑ Import backup','↑ 导入备份')}<input id="backup-file" type="file" accept=".json,application/json" hidden></div></section><section class="card"><h3>${b('Offline learning','离线学习')}</h3><p class="small">${offlineReady?b('✓ Lessons, questions and visual labs are cached. Python downloads are optional and may still require connectivity.','✓ 课程、题目与可视化实验已缓存。Python为可选下载，可能仍需要联网。'):b('Offline cache is not ready yet. Use HTTPS or localhost, then allow the first cache to finish.','离线缓存尚未就绪。请使用HTTPS或localhost，并等待首次缓存完成。')}</p>${button('check-update','Check for updates','检查更新')}</section><section class="card"><h3>${b('Start fresh','重新开始')}</h3><p class="muted small">${b('Clear local learning progress, notes and drafts. Export a backup first if you want to keep them.','清除本地学习进度、笔记和草稿。若需保留，请先导出备份。')}</p>${button('clear','Clear all progress','清除所有进度','danger')}</section></div></div>`;}
function about(){return `${title(['INDEPENDENT • OPEN • ATTRIBUTED','独立 · 开放 · 署名'],'About CAICP Academy.','关于CAICP Academy。')}<div class="license-panel"><section class="card"><h2>${b('A learning companion','学习伙伴')}</h2><p>${b('CAICP Academy is an independent bilingual learning resource, not an official certification service or designated textbook. Study routes are based on book v0.9 and its stated syllabus mapping, not a guarantee of current official requirements.','CAICP Academy是独立双语学习资源，不是官方认证服务或指定教材。路线依据教材v0.9及其大纲对应表，不保证代表当前官方要求。')}</p><p>${b('CAICP covers AI knowledge, Python programming and computational thinking. Consult the organizer for current requirements.','CAICP涵盖人工智能知识、Python编程与计算思维。当前要求请咨询主办方。')} <a href="https://ioaic.org.cn/" target="_blank" rel="noreferrer">IOAI China ↗</a></p></section><section class="card"><h2>${b('Book and adaptation credit','教材与改编署名')}</h2><p>陈峥 ·《从零开始学人工智能：中学生CAICP学习指南》· ${b('Public preview v0.9, released September 29, 2026.','公开试读版v0.9，2026年9月29日发布。')}</p><p>${b('Lessons, translations, recreated diagrams and book practice papers are adapted for this platform. Academy adds original checks and interactive activities. This is a modified adaptation, not the author’s original edition.','课程、翻译、重绘图示与教材模拟卷为本平台的改编内容。Academy新增原创检查题与交互活动。这是修改后的改编版，不是作者原版。')}</p><p><a href="https://github.com/UESTC1010/CAICP_Book" target="_blank" rel="noreferrer">${b('Book source and corrections','教材来源与勘误')} ↗</a></p></section><section class="card"><h2>${b('Two licenses, clearly separated','两种许可，明确区分')}</h2><p>${b('Application code: MIT, Copyright © 2026 WilliamH. Educational content: CC BY-NC-SA 4.0, including book-derived material and Academy’s original educational additions.','应用代码：MIT，Copyright © 2026 WilliamH。教育内容：CC BY-NC-SA 4.0，含教材改编与Academy原创教育内容。')}</p><p>${b('When reusing educational content, credit its creators and source, identify changes, keep use noncommercial, and distribute adaptations under the same license. The MIT code license does not remove those content conditions.','复用教育内容须署名作者与来源、注明修改、仅非商业使用，改编内容须以相同许可分享。代码的MIT许可不会取消教育内容的这些条件。')}</p><p><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer">CC BY-NC-SA 4.0 ↗</a> · <a href="./LICENSE">MIT</a> · <a href="./CONTENT-LICENSE.md">${b('Content notice','内容许可')}</a> · <a href="./THIRD-PARTY-NOTICES.md">${b('Third-party notices','第三方声明')}</a></p></section><section class="card"><h2>${b('Cited learning videos','有出处的学习视频')}</h2><p>${b('Every player credits its original creator and links the original source. External audiovisual works remain under their creators’ and providers’ terms; they do not inherit the Academy’s educational-content license. Loading a player connects to YouTube. Watching is optional and does not change lesson completion or quiz results.','每个播放器均注明原作者并链接原始来源。外部视听作品遵循其创作者与平台条款，不沿用Academy的教育内容许可。加载播放器会连接YouTube。观看为可选，不影响课程完成或测验成绩。')}</p><p>${b('Local captions and prompts switch language; the listed spoken language stays the same. Video streams require a network connection and may be restricted by the provider or region.','本地说明与提示可切换语言，所列语音语言不变。视频流需要联网，可能受平台或地区限制。')}</p><p><a href="./COVERAGE.md">${b('Book coverage record','教材覆盖记录')}</a> · <a href="./VIDEO-RESEARCH.md">${b('Video sources and verification','视频来源与验证')}</a> · <a href="./VALIDATION.md">${b('Validation notes','验证记录')}</a></p></section></div>`;}
function formatTime(ms){const sec=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function render(){const focus=document.activeElement?.id,sel=document.activeElement?.selectionStart,[screen,id]=route();document.documentElement.lang=s().settings.lang==='zh'?'zh-CN':'en';document.body.classList.toggle('dark',s().settings.theme==='dark');const nav=[['home','◫','Overview','学习概览'],['learn','▤','Learn','课程'],['labs','⠿','Visual labs','可视化实验'],['python','⌘','Python studio','Python练习'],['practice','✎','Practice','练习'],['review','↻','Review notebook','复习笔记'],['glossary','Aa','Glossary','术语表'],['settings','⚙','Settings','设置']];const active={lesson:'learn',lab:'labs',quiz:'practice'}[screen]||screen;const body={home:dashboard,learn,lesson:()=>lesson(id),practice,quiz,review:reviews,labs,lab:()=>LABS.some(x=>x[0]===id)?renderLab(id,b,esc):empty(),python,glossary,settings,about}[screen]?.()??empty();const markup=`<aside class="sidebar"><a class="brand" href="#home"><img src="./assets/favicon.svg" alt=""><div><strong>CAICP</strong><small>ACADEMY</small></div></a><div class="nav-caption">${b('YOUR WORKSPACE','你的学习空间')}</div><nav class="nav" aria-label="${b('Main navigation','主导航')}">${nav.map(([url,icon,en,zh])=>`<a href="#${url}" class="${url===active?'active':''}" ${url===active?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${b(en,zh)}</a>`).join('')}</nav><div class="sidebar-foot"><div class="small-leaf">✧</div><p>${b('Understanding grows<br>one idea at a time.','理解一点一点生长。')}</p><p><a href="#about">${b('About & licenses','关于与许可')} ↗</a></p><span class="offline-label">${offlineReady?b('✓ Core learning available offline','✓ 核心学习可离线使用'):b('Preparing offline learning…','准备离线学习…')}</span></div></aside><div class="shell"><header class="topbar"><span class="breadcrumb">${b('Your learning journey','你的学习旅程')} <span aria-hidden="true"> / </span> ${b(nav.find(n=>n[0]===active)?.[2]||'About',nav.find(n=>n[0]===active)?.[3]||'关于')}</span><div class="top-actions"><span class="pill"><span class="saved-dot"></span>${store.error?b('Memory only','仅内存'):b('Saved locally','本地保存')}</span>${button('language',s().settings.lang==='en'?'EN / 中文':'中文 / EN',s().settings.lang==='en'?'EN / 中文':'中文 / EN','language-switch',`aria-label="${b('Switch to Chinese','切换到英文')}"`)}${button('theme',s().settings.theme==='light'?'☾':'☀',s().settings.theme==='light'?'☾':'☀','',`aria-label="${b('Toggle appearance','切换外观')}"`)}</div></header><main id="main" tabindex="-1"><div id="notices">${store.error?`<div id="storage-warning" class="notice warning" role="alert">${b('Browser storage is unavailable or could not be read. Your current work stays in memory; export it before closing this page.','浏览器存储不可用或无法读取。当前记录保留在内存中，请关闭页面前导出。')} ${button('export','Export now','立即导出')}</div>`:''}${registration?.waiting?`<div class="notice">${b('An updated version is ready. Your saved learning record will be retained.','新版已就绪，将保留已保存的学习记录。')} ${button('apply-update','Update now','立即更新')}</div>`:''}${s().active&&!s().active.submittedAt&&screen!=='quiz'?`<div class="notice">${b('An unfinished attempt is saved.','已保存未完成的练习。')} ${link('quiz','Resume →','继续 →')}</div>`:''}</div>${body}<footer class="footer">CAICP Academy · ${b('Independent learning resource','独立学习资源')} · <a href="#about">${b('Sources & licenses','来源与许可')}</a> · ${b('Progress belongs to this browser.','进度保存在此浏览器中。')}</footer></main></div>`;if(screen==='lesson'&&renderedLesson===id)patchLearningDOM(root,markup);else root.innerHTML=markup;renderedLesson=screen==='lesson'?id:null;if(focus){const el=document.getElementById(focus);if(el){el.focus({preventScroll:true});if(typeof sel==='number'&&el.setSelectionRange)try{el.setSelectionRange(sel,sel);}catch{}}}}
function download(text,name=`caicp-progress-${new Date().toISOString().slice(0,10)}.json`){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmDialog(en,zh,detailEn,detailZh,onConfirm){document.querySelector('dialog')?.remove();const dlg=document.createElement('dialog');dlg.innerHTML=`<h2>${b(en,zh)}</h2><p>${b(detailEn,detailZh)}</p><div class="flex wrap">${button('dialog-cancel','Cancel','取消')}${button('dialog-confirm','Confirm','确认','primary')}</div>`;document.body.append(dlg);dlg.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='dialog-cancel'){dlg.close();dlg.remove();}if(action==='dialog-confirm'){dlg.close();dlg.remove();onConfirm();}});dlg.addEventListener('cancel',()=>dlg.remove());dlg.showModal();}
function start(questionIds,kind,title){if(!questionIds.length){notify('Nothing to review yet. Try a topic check first.','暂无复习题，请先做主题检查。');return;}const begin=()=>{if(s().active&&!s().active.submittedAt)submit(false);const started=now();s().active={id:globalThis.crypto?.randomUUID?.()||`attempt-${started}-${Math.random()}`,kind,title,questionIds,index:0,answers:{},flags:{},graded:{},startedAt:started,deadline:kind==='exam'?started+90*60000:null,submittedAt:null};save();if(location.hash==='#quiz')render();else location.hash='quiz';};if(s().active&&!s().active.submittedAt)confirmDialog('Finish the current attempt?','结束当前练习？','Its answers will be saved as a completed attempt before starting the new one.','开始新练习前，当前答案将保存为已完成记录。',begin);else begin();}
function submit(repaint=true){const a=s().active;if(!a||a.submittedAt)return;for(const id of a.questionIds)recordResponse(s(),questions.get(id),a.answers[id]||[],a.id);a.submittedAt=now();a.score=grade(a,questions);s().attempts.push(structuredClone(a));if(s().attempts.length>1000)s().attempts.shift();save();if(repaint)render();}
root.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id,a=s().active;
 if(action==='video-load'){activateVideo(root,id,videoCatalog,s().settings.lang);return;}
 if(action==='video-close'){const stage=[...root.querySelectorAll('[data-video-slot]')].find(x=>x.dataset.videoSlot===id);stage?.replaceChildren();render();return;}
 if(action==='concept-jump'){e.preventDefault();const target='#lesson/'+route()[1]+'/'+id;if(location.hash===target)jumpToConcept(id);else location.hash=target;return;}
 if(action==='book-code'){const block=concepts.get(id);if(!block?.code)return;const ex=EXERCISES.find(x=>x.id===(block.exercise||'basics'));const draft=s().python.drafts[ex.id];if(draft&&draft!==block.code){const url=URL.createObjectURL(new Blob([draft],{type:'text/x-python;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='caicp-previous-'+ex.id+'-draft.py';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}stopPython();s().python.exercise=ex.id;s().python.drafts[ex.id]=block.code;s().python.inputs[ex.id]=block.input||'';pythonView.output='';pythonView.plots=[];pythonView.hint=false;save();location.hash='python';return;}

 if(action==='language'){s().settings.lang=s().settings.lang==='en'?'zh':'en';save();render();}
 if(action==='theme'){s().settings.theme=s().settings.theme==='light'?'dark':'light';save();render();}
 if(action==='bookmark'){const i=s().bookmarks.indexOf(id);if(i>=0)s().bookmarks.splice(i,1);else s().bookmarks.push(id);save();render();}
 if(action==='complete'){const i=s().completed.indexOf(id);if(i>=0)s().completed.splice(i,1);else s().completed.push(id);save();render();notify('Lesson completion updated.','课程完成状态已更新。');}
 if(action==='lesson-quiz')start(lessons.get(id).questionIds,'practice',lessons.get(id).title);
 if(action==='paper-practice'||action==='paper-exam'){const p=exams.papers.find(x=>x.id===id);start(p.questionIds,action==='paper-exam'?'exam':'practice',p.title);}
 if(action==='diagnostic'){const routeIds=curriculum.routes[s().settings.route];const chosen=diagnosticQuestions(routeIds,lessons);start(chosen,'diagnostic',{en:'Route diagnostic · '+s().settings.route,zh:'路线诊断 · '+s().settings.route});}
 if(action==='due-review'){const due=stats().due;if(!due.length){location.hash='practice';notify('Answer some checks to create your spaced-review queue.','完成检查题即可建立间隔复习队列。');}else start(due.slice(0,20),'review',{en:'Today’s spaced review',zh:'今日间隔复习'});}
 if(action==='mistake-review')start(stats().mistakes.slice(-20),'review',{en:'Mistake practice',zh:'错题练习'});
 if(action==='question-practice')start([id],'review',{en:'Revisit one idea',zh:'重温一个概念'});
 if(action==='check'&&a&&!a.submittedAt&&a.kind!=='exam'){const q=questions.get(a.questionIds[a.index]),answer=a.answers[q.id]||[];if(!answer.length)return;recordResponse(s(),q,answer,a.id);a.graded[q.id]=true;save();render();}
 if(action==='flag'&&a){const id=a.questionIds[a.index];a.flags[id]=!a.flags[id];save();render();}
 if(action==='quiz-prev'&&a&&a.index>0){a.index--;save();render();}
 if(action==='quiz-next'&&a&&a.index<a.questionIds.length-1){a.index++;save();render();}
 if(action==='quiz-jump'&&a){a.index=Number(el.dataset.index);save();render();}
 if(action==='submit'&&a&&!a.submittedAt){const blank=a.questionIds.filter(id=>!a.answers[id]?.length).length;confirmDialog('Submit this attempt?','提交本次练习？',`${blank} unanswered. Answers and explanations will become available; this attempt will be saved.`,`${blank}题未答。提交后可查看答案与解析，本次练习将保存。`,()=>submit());}
 if(action==='retry'&&a)start([...a.questionIds],a.kind,a.title);
 if(action==='attempt-open'){const old=s().attempts.find(x=>x.id===id);if(old){if(a&&!a.submittedAt){notify('Finish your active attempt before opening a previous result.','请先完成当前练习，再查看历史结果。');location.hash='quiz';}else{s().active=structuredClone(old);save();location.hash='quiz';}}}
 if(action==='lab-reset'){resetLab(labState.id);render();}if(action==='lab-back'){labState.step=Math.max(0,labState.step-1);render();}if(action==='lab-step'){labState.step++;render();}
 if(action==='python-run'){const ex=EXERCISES.find(x=>x.id===s().python.exercise);runPython(ex,s().python.drafts[ex.id]??ex.code,s().python.inputs[ex.id]??ex.input,updatePython);}
 if(action==='python-stop'){stopPython();updatePython();}
 if(action==='python-reset'){const ex=EXERCISES.find(x=>x.id===s().python.exercise);s().python.drafts[ex.id]=ex.code;s().python.inputs[ex.id]=ex.input;save();render();}
 if(action==='python-hint'){pythonView.hint=!pythonView.hint;render();}
 if(action==='focus-start'){s().focusEndsAt=now()+25*60000;save();render();}if(action==='focus-stop'){s().focusEndsAt=null;save();render();}
 if(action==='export'){download(store.export());notify('Progress backup downloaded.','进度备份已下载。');}
 if(action==='import')document.querySelector('#backup-file').click();
 if(action==='clear')confirmDialog('Clear all local progress?','清除全部本地进度？','This removes your answers, notes and Python drafts. Export first if you want a copy.','将移除答案、笔记和Python草稿。如需副本，请先导出。',()=>{stopPython();store.reset();location.hash='home';render();});
 if(action==='check-update'){registration?.update().then(()=>notify('Checked for a new version.','已检查新版本。')).catch(()=>notify('Could not check while offline.','离线时无法检查更新。'));if(!registration)notify('Offline support requires HTTPS or localhost and service workers.','离线支持需要HTTPS或localhost及服务工作线程。');}
 if(action==='apply-update'&&registration?.waiting){if(a&&!a.submittedAt)notify('Finish your active attempt before updating the site.','更新网站前请先完成当前练习。');else{save();registration.waiting.postMessage('ACTIVATE');}}
});
root.addEventListener('input',e=>{const el=e.target;if(el.id==='lesson-notes'){s().notes[el.dataset.lesson]=el.value;save();}if(el.id==='python-code'){s().python.drafts[s().python.exercise]=el.value;save();}if(el.id==='python-input'){s().python.inputs[s().python.exercise]=el.value;save();}if(el.id==='lesson-search'){search=el.value;render();}if(el.id==='glossary-search'){glossarySearch=el.value;render();}});
root.addEventListener('keydown',e=>{if(e.target.id==='python-code'&&e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');s().python.drafts[s().python.exercise]=el.value;save();}});
root.addEventListener('change',async e=>{const el=e.target,a=s().active;
 if(el.name==='answer'&&a&&!a.submittedAt&&!a.graded[a.questionIds[a.index]]){const q=questions.get(a.questionIds[a.index]);if(q.type==='multiple'){const old=a.answers[q.id]||[];a.answers[q.id]=el.checked?[...old,Number(el.value)]:old.filter(x=>x!==Number(el.value));}else a.answers[q.id]=[Number(el.value)];save();render();}
 if(el.id==='route-select'){s().settings.route=el.value;save();render();}
 if(el.id==='level-filter'){levelFilter=el.value;render();}
 if(el.id==='goal-input'){const n=Number(el.value);if(Number.isInteger(n)&&n>=0&&n<=100){s().settings.dailyGoal=n;save();}else{notify('Choose a whole-number goal from 0 to 100.','请选择0到100的整数目标。');el.value=s().settings.dailyGoal;}}
 if(el.id==='theme-select'){s().settings.theme=el.value;save();render();}
 if(el.dataset.labParam){labState.params[el.dataset.labParam]=el.value;labState.step=0;render();}
 if(el.id==='exercise-select'){if(['running','loading'].includes(pythonView.status))stopPython();s().python.exercise=el.value;pythonView.hint=false;pythonView.output='';pythonView.plots=[];save();render();}
 if(el.id==='backup-file'){const file=el.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error();pendingImport=decodeBackup(await file.text(),ids);const incoming=pendingImport;confirmDialog('Replace progress with this backup?','用此备份替换进度？',`${incoming.completed.length} completed lessons, ${incoming.responses.length} answers, ${Object.keys(incoming.notes).length} notes. Your current progress will download as a safety backup first.`,`${incoming.completed.length}节已完成，${incoming.responses.length}条答题，${Object.keys(incoming.notes).length}条笔记。替换前会下载当前进度的安全备份。`,()=>{download(store.export(),`caicp-before-import-${Date.now()}.json`);stopPython();store.replace(incoming);pendingImport=null;render();notify('Backup imported.','备份已导入。');});}catch{notify('Invalid, oversized, or unsupported backup. Your progress has not changed.','备份无效、过大或版本不支持。当前进度未改变。');}el.value='';}
});
window.addEventListener('hashchange',()=>{render();if(route()[0]==='lesson'&&route()[2])jumpToConcept(route()[2]);else{window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});}});
setInterval(()=>{const a=s().active;if(expired(a)){submit();notify('Time is up. Your saved answers have been submitted.','时间已到，已提交保存的答案。');}const clock=document.querySelector('#exam-clock');if(clock&&a?.deadline)clock.textContent=formatTime(a.deadline-now());if(s().focusEndsAt&&now()>=s().focusEndsAt){s().focusEndsAt=null;save();notify('Focus session complete. Take a short break.','专注结束，休息一下。');if(route()[0]==='home')render();}const focus=document.querySelector('#focus-clock');if(focus&&s().focusEndsAt)focus.textContent=formatTime(s().focusEndsAt-now());},1000);
render();
if(route()[0]==='lesson'&&route()[2])jumpToConcept(route()[2]);
if('serviceWorker' in navigator){let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;location.reload();}});navigator.serviceWorker.register('./sw.js').then(reg=>{registration=reg;reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting)render();});});render();}).catch(()=>{});navigator.serviceWorker.ready.then(()=>{offlineReady=true;render();}).catch(()=>{});}

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main')?.focus();});
// Optional browser-native tools use the same curriculum and navigation as the UI.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tools=[
  {name:'search_caicp_lessons',description:'Read lesson matches in the currently selected language; does not change progress.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(typeof input?.query!=='string'||input.query.length>100)throw Error('A query of at most 100 characters is required');return curriculum.lessons.filter(l=>JSON.stringify([l.id,l.title,l.body,expandedSections.get(l.id)]).toLowerCase().includes(input.query.toLowerCase())).slice(0,20).map(l=>({id:l.id,title:loc(l.title),page:l.page}));}},
  {name:'read_caicp_study_summary',description:'Read completion and review counts; returns no personal notes or code.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const st=stats();return {route:s().settings.route,completed:s().completed.length,questionsAnswered:st.total,reviewsDue:st.due.length};}},
  {name:'open_caicp_lesson',description:'Navigate to a lesson and save it as the last visited lesson; does not mark completion or answer questions.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:[...lessons.keys()]}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!lessons.has(input?.lessonId))throw Error('Unknown lesson');s().lastLesson=input.lessonId;save();history.replaceState(null,'',`#lesson/${input.lessonId}`);render();return {opened:input.lessonId,title:loc(lessons.get(input.lessonId).title)};}}
 ];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
}

root.addEventListener("toggle",event=>{const detail=event.target;if(detail.tagName!=="DETAILS"||detail.open)return;const stages=[...detail.querySelectorAll("[data-video-slot]")].filter(n=>n.querySelector("iframe"));if(stages.length){for(const stage of stages)stage.replaceChildren();render();}},true);
